static inline bool
ProcAffectsDataHorizon(PGPROC *proc, int8 statusFlags, bool in_recovery)
{
	return proc->databaseId == MyDatabaseId ||
		MyDatabaseId == InvalidOid ||
		(statusFlags & PROC_AFFECTS_ALL_HORIZONS) ||
