bool
TwoPhaseGetGidByXid(TransactionId xid, char *gid, int gidsize)
{
	bool		found = false;

	if (!TransactionIdIsValid(xid))
		return false;

	LWLockAcquire(TwoPhaseStateLock, LW_SHARED);
	for (int i = 0; i < TwoPhaseState->numPrepXacts; i++)
	{
		GlobalTransaction gxact = TwoPhaseState->prepXacts[i];

		if (XidFromFullTransactionId(gxact->fxid) == xid)
		{
			strlcpy(gid, gxact->gid, gidsize);
			found = true;
			break;
		}
	}
	LWLockRelease(TwoPhaseStateLock);

	return found;
}

LWLockAcquire(ReplicationSlotControlLock, LW_SHARED);
for (int i = 0; i < max_replication_slots + max_repack_replication_slots; i++)
{
	ReplicationSlot *s = &ReplicationSlotCtl->replication_slots[i];
	TransactionId slot_xmin;

	if (!s->in_use)
		continue;

	SpinLockAcquire(&s->mutex);
	slot_xmin = catalog ? s->effective_catalog_xmin : s->effective_xmin;
	SpinLockRelease(&s->mutex);

	if (xid == slot_xmin)
	{
		strlcpy(name, NameStr(s->data.name), namesize);
		found = true;
		break;
	}
}
LWLockRelease(ReplicationSlotControlLock);
